<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Employee/employee_list')}" class="on">从业人员列表</a>|					<a href="{pigcms{:U('Employee/employee_examine')}">审核列表</a>|                    <a href="{pigcms{:U('Employee/employee_examine_refused')}">审核拒绝列表</a>|				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('Employee/employee_list')}" method="get">							<input type="hidden" name="c" value="Employee"/>							<input type="hidden" name="a" value="employee_list"/>							筛选: 							<if condition="$admin_area neq 3">							<div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}" area_id="{pigcms{$_GET.area_id}" style="display:inline"></div>							</if>							<input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="true_name" <if condition="$_GET['searchtype'] eq 'true_name'">selected="selected"</if>>姓名</option>								<option value="nickname" <if condition="$_GET['searchtype'] eq 'nickname'">selected="selected"</if>>昵称</option>								 <option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>手机号</option>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;														状态:							<select name="is_open">								<option value="" <if condition="$_GET['is_open'] eq ''">selected="selected"</if>>全部</option>								<option value="1" <if condition="$_GET['is_open'] eq '1'">selected="selected"</if>>开启</option>								<option value="0" <if condition="$_GET['is_open'] eq '0'">selected="selected"</if>>关闭</option>							</select>							<input type="submit" style="margin-right:20px;" value="查询" class="button"/><!--							<a href="{pigcms{:U('Employee/employee_push',$_GET)}"class="button" style="margin-left: 200px;">导出{pigcms{$config['employee_alias']}</a>-->						</form>											</td>				</tr>			</table>							<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col> <col><col><col><col width="120"><col><col><col><col><col><col><col width="80" align="center"> </colgroup>						<thead>							<tr>								<th>编号</th>								<th>注册昵称</th>								<th>从业者姓名</th>								<th>业务联系电话</th>								<th>注册手机号</th>								<th>主页点击数</th>								<th>粉丝数</th>								<th>收藏数</th>                                <th>点赞数</th>                                <th>平均评分</th>								<th>账户余额</th>                                <th>是否关联店铺</th>                                <th>所在区域</th>                                <th>状态</th>                                <th>查看评论</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="!empty($employee_list)">								<volist name="employee_list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.nickname}</td>										<td>{pigcms{$vo.true_name}</td>										<td>{pigcms{$vo.business_phone}</td>										<td>{pigcms{$vo.phone}</td>										<td>{pigcms{$vo.click_num}</td>										<td>{pigcms{$vo.fans_num}                                            <if condition="$config.open_user_spread eq 1 && $vo.openid neq ''">                                                | <a href="{pigcms{:U('User/spread_user',array('action'=>'spread_user','openid'=>$vo['openid'],'uid'=>$vo['uid']))}">推广用户明细</a>                                            </if>                                        </td>										<td>{pigcms{$vo.collect_num}</td>										<td>{pigcms{$vo.thumb_num}</td>                                        <td>                                            <if condition="$vo.score_average gt 0">{pigcms{$vo.score_average}<else/>暂无评分</if>                                        </td>                                        <td>{pigcms{$vo.now_money}</td>										<td>											<if condition="$vo.is_relate_store eq 0">												否											<else />												是											</if>										</td>                                        <td>                                            <if condition="$vo['province_name'] || $vo['city_name'] || $vo['area_name']">                                                {pigcms{$vo.province_name} {pigcms{$vo.city_name} {pigcms{$vo.area_name}                                                <else/>                                                -                                            </if>                                        </td>                                        <td>                                            <if condition="$vo['is_open'] eq 1">                                                开启                                                <else/>                                                关闭                                            </if>                                        </td>                                        <td>                                            <a href="{pigcms{:U('Employee/reply_list',array('employee_id'=>$vo['id']))}">查看</a>                                        </td>										<td class="textcenter">                                            <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Employee/edit',array('id'=>$vo['id'],'frame_show'=>true))}','查看信息',680,560,true,false,false,false,'detail',true);">查看</a>                                            &nbsp; | &nbsp;<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Employee/edit',array('id'=>$vo['id']))}','编辑信息',680,560,true,false,false,editbtn,'edit',true);">编辑</a>                                            &nbsp; | &nbsp;<a class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Employee/del_employee')}">删除</a>                                        </td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="14">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="14">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>		</div><script>   var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('Merchant/export_info')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>